mapper.select:
select from litemall_season_candidate where season_key = #{seasonKey} and `day` = #{day} and deleted = 0
and status = #{status}
order by score desc, goods_id asc

mapper.update:
update litemall_season_candidate
set status = #{toStatus}, update_time = now()
where season_key = #{seasonKey}
  and goods_id = #{goodsId}
  and `day` = #{day}
  and status = #{fromStatus}
  and deleted = 0
